package matteroverdrive.blockentity;

import matteroverdrive.item.ContractItem;
import matteroverdrive.menu.StarMapMenu;
import matteroverdrive.registry.ModBlockEntities;
import matteroverdrive.registry.ModEntities;
import matteroverdrive.starmap.StarMapCatalog;
import matteroverdrive.starmap.StarMapGalaxyData;
import net.minecraft.ChatFormatting;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ContainerData;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import javax.annotation.Nullable;
import java.util.UUID;

public class StarMapBlockEntity extends BlockEntity implements MenuProvider {
    public static final int ENCOUNTER_NONE=0,ENCOUNTER_ASTEROIDS=1,ENCOUNTER_SLINGSHOT=2,ENCOUNTER_ANDROID_INTERCEPT=3,ENCOUNTER_SIGNAL_ECHO=4,ENCOUNTER_HOSTILE_FLEET=5;
    public static final int ECON_NONE=0,ECON_SCOUT=1,ECON_COLONIZER=2,ECON_FACTORY=3,ECON_HANGAR=4,ECON_COLONIZE=5;
    private static final int SCOUT_BUILD_TICKS=3600,COLONIZER_BUILD_TICKS=5000,FACTORY_BUILD_TICKS=8000,HANGAR_BUILD_TICKS=4800;
    private static final int FLEET_MAX_HULL=100,FLEET_MAX_SHIELD=60,FLEET_BASE_FIREPOWER=20,FLEET_ATTACK_COOLDOWN=20;
    private int currentQuadrant,currentStar,currentPlanet,destinationQuadrant,destinationStar,destinationPlanet;
    private boolean traveling;private long travelStartTime,travelEndTime;private int travelDuration;
    private int encounterCode,lastEncounterCode;private long encounterTriggerTime;private boolean encounterResolved=true;
    @Nullable private UUID fleetOwner;private int fleetHull=FLEET_MAX_HULL,fleetShield=FLEET_MAX_SHIELD,fleetFirepower=FLEET_BASE_FIREPOWER,fleetVictories;
    private boolean fleetCombat;private int enemyHull,enemyMaxHull,enemyFirepower;private long fleetCombatStarted,lastFleetAttack;
    private int scoutShips,colonizerShips,buildAction;private long buildEndTime;private int buildQuadrant,buildStar,buildPlanet;

    public StarMapBlockEntity(BlockPos pos,BlockState state){super(ModBlockEntities.STAR_MAP.get(),pos,state);}
    public static void tick(Level level,BlockPos pos,BlockState state,StarMapBlockEntity map){if(level.isClientSide)return;long t=level.getGameTime();map.finishBuildIfDue(t);map.resolveEncounterIfDue(level,t);map.finishTravelIfDue(t);}
    private StarMapGalaxyData.PlanetState currentState(){if(!(level instanceof ServerLevel sl))return new StarMapGalaxyData.PlanetState();return StarMapGalaxyData.get(sl).planet(currentQuadrant,currentStar,currentPlanet);}
    public ContainerData dataFor(Player viewer){return new ContainerData(){@Override public int get(int i){int a=0,d=0;for(var s:viewer.getInventory().items)if(s.getItem() instanceof ContractItem){a++;if(ContractItem.complete(s))d++;}var ps=currentState();return switch(i){case 0->a;case 1->d;case 2->currentQuadrant;case 3->currentStar;case 4->currentPlanet;case 5->destinationQuadrant;case 6->destinationStar;case 7->destinationPlanet;case 8->remainingTicks();case 9->travelDuration;case 10->traveling?1:0;case 11->encounterResolved?lastEncounterCode:encounterCode;case 12->encounterResolved?0:encounterRemainingTicks();case 13->encounterResolved?1:0;case 14->fleetHull;case 15->fleetShield;case 16->fleetFirepower;case 17->fleetCombat?1:0;case 18->enemyHull;case 19->enemyMaxHull;case 20->fleetVictories;case 21->fleetAttackCooldown();case 22->scoutShips;case 23->colonizerShips;case 24->buildAction;case 25->buildRemainingTicks();case 26->!ps.hasOwner()?0:ps.isOwner(viewer.getUUID())?1:2;case 27->ps.hasBase()?1:0;case 28->ps.hasShipFactory()?1:0;case 29->ps.hangars();case 30->ps.fleetCapacity();default->0;};}@Override public void set(int i,int v){}@Override public int getCount(){return 31;}};}

    private boolean bindCommanderAndHomeworld(ServerPlayer p){if(!(level instanceof ServerLevel sl))return false;if(fleetOwner!=null&&!fleetOwner.equals(p.getUUID()))return false;if(fleetOwner==null){fleetOwner=p.getUUID();StarMapGalaxyData.get(sl).ensureHomeworld(currentQuadrant,currentStar,currentPlanet,fleetOwner);setChanged();}return true;}
    public boolean requestTravel(ServerPlayer p,int q,int s,int pl){if(level==null||level.isClientSide||!StarMapCatalog.validPosition(q,s,pl))return false;finishTravelIfDue(level.getGameTime());if(!bindCommanderAndHomeworld(p)){msg(p,"Star Map fleet is bound to another commander.",ChatFormatting.RED);return false;}if(buildAction!=ECON_NONE){msg(p,"Star Map: shipyard construction must finish before departure.",ChatFormatting.YELLOW);return false;}if(fleetCombat){msg(p,"Star Map: hostile fleet engagement must be resolved first.",ChatFormatting.RED);return false;}if(traveling){msg(p,"Star Map: a journey is already in progress.",ChatFormatting.YELLOW);return false;}if(q==currentQuadrant&&s==currentStar&&pl==currentPlanet){msg(p,"Star Map: already at that destination.",ChatFormatting.YELLOW);return false;}int duration=StarMapCatalog.travelTicks(currentQuadrant,currentStar,currentPlanet,q,s,pl);if(duration<=0)return false;destinationQuadrant=q;destinationStar=s;destinationPlanet=pl;traveling=true;travelDuration=duration;travelStartTime=level.getGameTime();travelEndTime=travelStartTime+duration;fleetShield=FLEET_MAX_SHIELD;scheduleEncounter(duration);setChanged();var target=StarMapCatalog.planet(q,s,pl);msg(p,"Star Map journey started: "+target.name()+" ("+Math.max(1,duration/20)+"s)",ChatFormatting.AQUA);return true;}

    public boolean requestEconomyAction(ServerPlayer p,int action){if(!(level instanceof ServerLevel sl)||action<ECON_SCOUT||action>ECON_COLONIZE)return false;if(!bindCommanderAndHomeworld(p)){msg(p,"Star Map economy is bound to another commander.",ChatFormatting.RED);return false;}if(traveling||fleetCombat){msg(p,"Star Map: economy actions require the fleet to be at a planet.",ChatFormatting.YELLOW);return false;}StarMapGalaxyData data=StarMapGalaxyData.get(sl);var ps=data.planet(currentQuadrant,currentStar,currentPlanet);if(action==ECON_COLONIZE){if(ps.hasOwner()){msg(p,"Colonization failed: this planet already has an owner.",ChatFormatting.YELLOW);return false;}if(colonizerShips<=0){msg(p,"Colonization requires a completed Colonizer ship.",ChatFormatting.RED);return false;}if(!data.colonize(currentQuadrant,currentStar,currentPlanet,p.getUUID()))return false;colonizerShips--;setChanged();msg(p,"Colonizer deployed: Base established and planet ownership secured.",ChatFormatting.GREEN);return true;}if(!ps.isOwner(p.getUUID())||!ps.hasBase()){msg(p,"Construction requires your colony Base on the current planet.",ChatFormatting.RED);return false;}if(buildAction!=ECON_NONE){msg(p,"Star Map shipyard: another project is already building.",ChatFormatting.YELLOW);return false;}int duration;switch(action){case ECON_SCOUT->{if(!ps.hasShipFactory()){msg(p,"Scout construction requires a Ship Factory.",ChatFormatting.RED);return false;}if(scoutShips+colonizerShips>=ps.fleetCapacity()){msg(p,"No fleet berth available. Build a Ship Hangar.",ChatFormatting.RED);return false;}duration=SCOUT_BUILD_TICKS;}case ECON_COLONIZER->{if(!ps.hasShipFactory()){msg(p,"Colonizer construction requires a Ship Factory.",ChatFormatting.RED);return false;}if(scoutShips+colonizerShips>=ps.fleetCapacity()){msg(p,"No fleet berth available. Build a Ship Hangar.",ChatFormatting.RED);return false;}duration=COLONIZER_BUILD_TICKS;}case ECON_FACTORY->{if(ps.hasShipFactory()){msg(p,"This planet already has a Ship Factory.",ChatFormatting.YELLOW);return false;}duration=FACTORY_BUILD_TICKS;}case ECON_HANGAR->{if(ps.hangars()>=8){msg(p,"This colony has reached the current Hangar limit.",ChatFormatting.YELLOW);return false;}duration=HANGAR_BUILD_TICKS;}default->{return false;}}buildAction=action;buildQuadrant=currentQuadrant;buildStar=currentStar;buildPlanet=currentPlanet;buildEndTime=level.getGameTime()+duration;setChanged();msg(p,"Star Map construction started: "+economyName(action)+" ("+Math.max(1,duration/20)+"s)",ChatFormatting.AQUA);return true;}
    private void finishBuildIfDue(long now){if(buildAction==ECON_NONE||level==null||now<buildEndTime||!(level instanceof ServerLevel sl))return;int action=buildAction;buildAction=ECON_NONE;buildEndTime=0;StarMapGalaxyData data=StarMapGalaxyData.get(sl);boolean ok=fleetOwner!=null&&data.planet(buildQuadrant,buildStar,buildPlanet).isOwner(fleetOwner);if(ok)switch(action){case ECON_SCOUT->scoutShips++;case ECON_COLONIZER->colonizerShips++;case ECON_FACTORY->data.addShipFactory(buildQuadrant,buildStar,buildPlanet,fleetOwner);case ECON_HANGAR->data.addHangar(buildQuadrant,buildStar,buildPlanet,fleetOwner);default->{}}setChanged();if(ok)announce(level,"Star Map construction complete: "+economyName(action)+".",ChatFormatting.GREEN);}
    private static String economyName(int action){return switch(action){case ECON_SCOUT->"Scout Ship";case ECON_COLONIZER->"Colonizer Ship";case ECON_FACTORY->"Ship Factory";case ECON_HANGAR->"Ship Hangar";case ECON_COLONIZE->"Colonize";default->"Idle";};}

    public boolean requestFleetAttack(ServerPlayer p){if(level==null||level.isClientSide||!fleetCombat||!traveling)return false;if(fleetOwner==null||!fleetOwner.equals(p.getUUID())){msg(p,"Star Map: only the fleet commander can fire.",ChatFormatting.RED);return false;}long now=level.getGameTime();if(now-lastFleetAttack<FLEET_ATTACK_COOLDOWN)return false;lastFleetAttack=now;enemyHull=Math.max(0,enemyHull-fleetFirepower);if(enemyHull<=0){fleetVictories++;fleetCombat=false;travelEndTime+=Math.max(0L,now-fleetCombatStarted);fleetCombatStarted=0;msg(p,"Hostile fleet destroyed. Navigation resumed.",ChatFormatting.GREEN);setChanged();return true;}enemyVolley(p);setChanged();return true;}
    private void enemyVolley(ServerPlayer p){int damage=enemyFirepower,shield=Math.min(fleetShield,damage);fleetShield-=shield;damage-=shield;if(damage>0)fleetHull=Math.max(0,fleetHull-damage);if(fleetHull>0){msg(p,"Fleet exchange: enemy hull "+enemyHull+"/"+enemyMaxHull+", your hull "+fleetHull+"/"+FLEET_MAX_HULL,ChatFormatting.YELLOW);return;}fleetCombat=false;traveling=false;destinationQuadrant=currentQuadrant;destinationStar=currentStar;destinationPlanet=currentPlanet;travelStartTime=travelEndTime=encounterTriggerTime=0;encounterResolved=true;fleetHull=35;fleetShield=0;fleetCombatStarted=0;msg(p,"Fleet disabled. Emergency retreat returned navigation to the last safe planet.",ChatFormatting.RED);}
    private void scheduleEncounter(int duration){encounterCode=ENCOUNTER_NONE;encounterTriggerTime=0;encounterResolved=true;lastEncounterCode=ENCOUNTER_NONE;if(duration<80)return;int h=Math.floorMod(currentQuadrant*97+currentStar*53+currentPlanet*31+destinationQuadrant*211+destinationStar*127+destinationPlanet*71+duration,5);encounterCode=h+1;encounterTriggerTime=travelStartTime+Math.max(30,duration/2L);encounterResolved=false;}
    private void resolveEncounterIfDue(Level level,long t){if(!traveling||encounterResolved||encounterCode==0||t<encounterTriggerTime)return;switch(encounterCode){case ENCOUNTER_ASTEROIDS->{travelEndTime+=100;announce(level,"Star Map encounter: asteroid field. Route slowed by 5 seconds.",ChatFormatting.YELLOW);}case ENCOUNTER_SLINGSHOT->{long r=Math.min(80,Math.max(20,travelDuration/6L));travelEndTime=Math.max(t+20,travelEndTime-r);announce(level,"Star Map encounter: gravitational slingshot. ETA reduced.",ChatFormatting.GREEN);}case ENCOUNTER_ANDROID_INTERCEPT->{travelEndTime+=120;spawnBoardingParty(level);announce(level,"Star Map encounter: Rogue Android intercept. Boarding party detected!",ChatFormatting.RED);}case ENCOUNTER_SIGNAL_ECHO->{travelEndTime+=40;announce(level,"Star Map encounter: anomalous signal echo. Navigation recalibration required.",ChatFormatting.AQUA);}case ENCOUNTER_HOSTILE_FLEET->beginFleetCombat(level,t);default->{}}lastEncounterCode=encounterCode;encounterResolved=true;encounterTriggerTime=0;travelDuration=(int)Math.max(1,Math.min(Integer.MAX_VALUE,travelEndTime-travelStartTime));setChanged();}
    private void beginFleetCombat(Level level,long t){int threat=Math.floorMod(destinationQuadrant*7+destinationStar*11+destinationPlanet*13,4);enemyMaxHull=60+threat*20;enemyHull=enemyMaxHull;enemyFirepower=8+threat*3;fleetCombat=true;fleetCombatStarted=t;lastFleetAttack=t-FLEET_ATTACK_COOLDOWN;announce(level,"Star Map encounter: hostile fleet contact. Navigation paused - engage from the Star Map console.",ChatFormatting.RED);}
    private void spawnBoardingParty(Level level){if(!(level instanceof ServerLevel sl))return;for(int i=0;i<3;i++){Mob a=(i==2?ModEntities.RANGED_ROGUE_ANDROID.get():ModEntities.ROGUE_ANDROID.get()).create(sl);if(a==null)continue;double ox=i==0?2.5:i==1?-2.5:.5,oz=i==2?2.5:-1.5;a.moveTo(worldPosition.getX()+.5+ox,worldPosition.getY()+1,worldPosition.getZ()+.5+oz,sl.random.nextFloat()*360,0);sl.addFreshEntity(a);}}
    private void announce(Level level,String text,ChatFormatting color){if(!(level instanceof ServerLevel sl))return;Component c=Component.literal(text).withStyle(color);for(ServerPlayer p:sl.players())if(p.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=1024)p.displayClientMessage(c,false);}
    private static void msg(ServerPlayer p,String s,ChatFormatting c){p.displayClientMessage(Component.literal(s).withStyle(c),true);}
    private int remainingTicks(){return !traveling||level==null?0:(int)Math.max(0,Math.min(Integer.MAX_VALUE,travelEndTime-level.getGameTime()));}private int encounterRemainingTicks(){return encounterResolved||level==null?0:(int)Math.max(0,Math.min(Integer.MAX_VALUE,encounterTriggerTime-level.getGameTime()));}private int fleetAttackCooldown(){return !fleetCombat||level==null?0:(int)Math.max(0,FLEET_ATTACK_COOLDOWN-(level.getGameTime()-lastFleetAttack));}private int buildRemainingTicks(){return buildAction==ECON_NONE||level==null?0:(int)Math.max(0,Math.min(Integer.MAX_VALUE,buildEndTime-level.getGameTime()));}
    private void finishTravelIfDue(long t){if(!traveling||fleetCombat||t<travelEndTime)return;currentQuadrant=destinationQuadrant;currentStar=destinationStar;currentPlanet=destinationPlanet;traveling=false;travelStartTime=travelEndTime=encounterTriggerTime=0;encounterResolved=true;fleetHull=Math.min(FLEET_MAX_HULL,fleetHull+10);fleetShield=FLEET_MAX_SHIELD;setChanged();}
    @Override protected void saveAdditional(CompoundTag tag){super.saveAdditional(tag);tag.putInt("CurrentQuadrant",currentQuadrant);tag.putInt("CurrentStar",currentStar);tag.putInt("CurrentPlanet",currentPlanet);tag.putInt("DestinationQuadrant",destinationQuadrant);tag.putInt("DestinationStar",destinationStar);tag.putInt("DestinationPlanet",destinationPlanet);tag.putBoolean("Traveling",traveling);tag.putLong("TravelStart",travelStartTime);tag.putLong("TravelEnd",travelEndTime);tag.putInt("TravelDuration",travelDuration);tag.putInt("EncounterCode",encounterCode);tag.putInt("LastEncounterCode",lastEncounterCode);tag.putLong("EncounterTrigger",encounterTriggerTime);tag.putBoolean("EncounterResolved",encounterResolved);if(fleetOwner!=null)tag.putUUID("FleetOwner",fleetOwner);tag.putInt("FleetHull",fleetHull);tag.putInt("FleetShield",fleetShield);tag.putInt("FleetFirepower",fleetFirepower);tag.putInt("FleetVictories",fleetVictories);tag.putBoolean("FleetCombat",fleetCombat);tag.putInt("EnemyHull",enemyHull);tag.putInt("EnemyMaxHull",enemyMaxHull);tag.putInt("EnemyFirepower",enemyFirepower);tag.putLong("FleetCombatStarted",fleetCombatStarted);tag.putLong("LastFleetAttack",lastFleetAttack);tag.putInt("ScoutShips",scoutShips);tag.putInt("ColonizerShips",colonizerShips);tag.putInt("BuildAction",buildAction);tag.putLong("BuildEnd",buildEndTime);tag.putInt("BuildQuadrant",buildQuadrant);tag.putInt("BuildStar",buildStar);tag.putInt("BuildPlanet",buildPlanet);}
    @Override public void load(CompoundTag tag){super.load(tag);currentQuadrant=tag.getInt("CurrentQuadrant");currentStar=tag.getInt("CurrentStar");currentPlanet=tag.getInt("CurrentPlanet");destinationQuadrant=tag.getInt("DestinationQuadrant");destinationStar=tag.getInt("DestinationStar");destinationPlanet=tag.getInt("DestinationPlanet");traveling=tag.getBoolean("Traveling");travelStartTime=tag.getLong("TravelStart");travelEndTime=tag.getLong("TravelEnd");travelDuration=tag.getInt("TravelDuration");encounterCode=tag.getInt("EncounterCode");lastEncounterCode=tag.getInt("LastEncounterCode");encounterTriggerTime=tag.getLong("EncounterTrigger");encounterResolved=!tag.contains("EncounterResolved")||tag.getBoolean("EncounterResolved");fleetOwner=tag.hasUUID("FleetOwner")?tag.getUUID("FleetOwner"):null;fleetHull=tag.contains("FleetHull")?tag.getInt("FleetHull"):FLEET_MAX_HULL;fleetShield=tag.contains("FleetShield")?tag.getInt("FleetShield"):FLEET_MAX_SHIELD;fleetFirepower=tag.contains("FleetFirepower")?tag.getInt("FleetFirepower"):FLEET_BASE_FIREPOWER;fleetVictories=tag.getInt("FleetVictories");fleetCombat=tag.getBoolean("FleetCombat");enemyHull=tag.getInt("EnemyHull");enemyMaxHull=tag.getInt("EnemyMaxHull");enemyFirepower=tag.getInt("EnemyFirepower");fleetCombatStarted=tag.getLong("FleetCombatStarted");lastFleetAttack=tag.getLong("LastFleetAttack");scoutShips=Math.max(0,tag.getInt("ScoutShips"));colonizerShips=Math.max(0,tag.getInt("ColonizerShips"));buildAction=tag.getInt("BuildAction");buildEndTime=tag.getLong("BuildEnd");buildQuadrant=tag.getInt("BuildQuadrant");buildStar=tag.getInt("BuildStar");buildPlanet=tag.getInt("BuildPlanet");if(!StarMapCatalog.validPosition(currentQuadrant,currentStar,currentPlanet))currentQuadrant=currentStar=currentPlanet=0;if(!StarMapCatalog.validPosition(destinationQuadrant,destinationStar,destinationPlanet)){destinationQuadrant=currentQuadrant;destinationStar=currentStar;destinationPlanet=currentPlanet;traveling=false;fleetCombat=false;}if(encounterCode<0||encounterCode>ENCOUNTER_HOSTILE_FLEET){encounterCode=0;encounterResolved=true;encounterTriggerTime=0;}if(buildAction<ECON_NONE||buildAction>ECON_HANGAR){buildAction=ECON_NONE;buildEndTime=0;}fleetHull=Math.max(0,Math.min(FLEET_MAX_HULL,fleetHull));fleetShield=Math.max(0,Math.min(FLEET_MAX_SHIELD,fleetShield));fleetFirepower=Math.max(1,fleetFirepower);if(!traveling)fleetCombat=false;}
    @Override public Component getDisplayName(){return Component.translatable("block.matteroverdrive.star_map");}@Nullable @Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new StarMapMenu(id,inventory,this);}
}
